<style lang="scss" scoped src="./donor-detail-block.scss"></style>

<script>
import { format } from "date-fns";
import differenceInDays from "date-fns/differenceInDays";
import differenceInMonths from "date-fns/differenceInMonths";
import { Component, Prop, Vue } from "vue-property-decorator";
import Select from "../../components/select/select.vue";
import TextInput from "../../components/text-input/text-input.vue";
import { has } from "../../util/has";
import {
  CurrencyNotation,
  CurrencyNotationValues,
  USStates
} from "../constants";

function integerPart(num) {
  return Math.floor(num);
}

function decimalPart(num) {
  const decimal = num.toFixed(2);
  const index = decimal.indexOf(".");

  return decimal.substr(index);
}

@Component({
  components: {
    Select,
    TextInput
  }
})
export default class DonorDetailBlock extends Vue {
  @Prop({
    type: String,
    default: ""
  })
  salutation;

  @Prop({
    type: Array,
    default: () => []
  })
  salutationValues;

  @Prop({
    type: String,
    default: ""
  })
  firstName;

  @Prop({
    type: String,
    default: ""
  })
  lastName;

  @Prop({
    type: String,
    default: ""
  })
  email;

  @Prop({
    type: String,
    default: ""
  })
  streetAddress;

  @Prop({
    type: String,
    default: ""
  })
  city;

  @Prop({
    type: String,
    default: ""
  })
  state;

  @Prop({
    type: String,
    default: ""
  })
  zip;

  @Prop({
    type: Number,
    default: 0
  })
  latestDonation;

  @Prop({
    type: Number,
    default: 0
  })
  totalDonation;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  @Prop({
    type: Date,
    default: () => new Date()
  })
  lastDonationTime;

  @Prop({
    type: Date,
    default: () => new Date()
  })
  firstDonationTime;

  @Prop({
    type: String,
    default: ""
  })
  status;

  @Prop({
    type: Date,
    default: new Date()
  })
  statusStartedDate;

  USStates = USStates;

  personalDetails = {
    salutation: "",
    firstName: "",
    lastName: "",
    email: "",
    streetAddress: "",
    city: "",
    state: "",
    zipCode: ""
  };

  beforeMount() {
    this.personalDetails.salutation = this.salutation;
    this.personalDetails.firstName = this.firstName;
    this.personalDetails.lastName = this.lastName;
    this.personalDetails.email = this.email;
    this.personalDetails.streetAddress = this.streetAddress;
    this.personalDetails.city = this.city;
    this.personalDetails.state = this.state;
    this.personalDetails.zipCode = this.zipCode;
  }

  get latestDonationInteger() {
    return integerPart(this.latestDonation).toLocaleString();
  }

  get latestDonationDecimal() {
    return decimalPart(this.latestDonation);
  }

  get lastDonationDateStr() {
    return format(this.lastDonationTime, "MMMM dd,y");
  }

  get totalDonationInteger() {
    return integerPart(this.totalDonation).toLocaleString("us");
  }

  get totalDonationDecimal() {
    return decimalPart(this.totalDonation);
  }

  get firstDonationDateStr() {
    return `Since ${format(this.firstDonationTime, "MMMM dd,y")}`;
  }

  get statusDurationStr() {
    const daysDiff = differenceInDays(new Date(), this.statusStartedDate);

    if (daysDiff <= 31) return `${daysDiff} days-`;

    const monthsDiff = differenceInMonths(new Date(), this.statusStartedDate);
    return `${monthsDiff} mo.-`;
  }

  handleChange() {
    /**
     * Emits when any change on this block happens
     *
     * @Event change
     */
    this.$emit("change", this.personalDetails);
  }

  handleChangeSalutation(value) {
    this.personalDetails.salutation = value;
    this.handleChange();
  }

  handleFirstNameInput(value) {
    this.personalDetails.firstName = value;
    this.handleChange();
  }

  handleLastNameInput(value) {
    this.personalDetails.lastName = value;
    this.handleChange();
  }

  handleStreeAddressInput(value) {
    this.personalDetails.streetAddress = value;
    this.handleChange();
  }

  handleCityInput(value) {
    this.personalDetails.city = value;
    this.handleChange();
  }

  handleStateChange(value) {
    this.personalDetails.state = value;
    this.handleChange();
  }

  handleZipInput(value) {
    this.personalDetails.zipCode = value;
    this.handleChange();
  }
}
</script>

<template>
  <div class="DonorDetailBlock">
    <div class="DonorDetailBlock__Left">
      <div class="DonorDetailBlock__Title">Personal Details</div>
      <div class="DonorDetailBlock__Personal">
        <div class="DonorDetailBlock__PersonalSmallBlock">
          <div class="DonorDetailBlock__SubTitle">Salutation</div>
          <Select 
            class="DonorDetailBlock__Salutation"
            search
            label="Salutation"
            :value="personalDetails.salutation"
            :items="salutationValues"
            @select="handleChangeSalutation"
          />
        </div>
        <div class="DonorDetailBlock__PersonalBlock">
          <div class="DonorDetailBlock__SubTitle">First Name</div>
          <TextInput
            class="DonorDetailBlock__NameInput"
            :defaultValue="firstName"
            @input="handleFirstNameInput"
          />
        </div>
        <div class="DonorDetailBlock__PersonalBlock">
          <div class="DonorDetailBlock__SubTitle">Last Name</div>
          <TextInput
            class="DonorDetailBlock__NameInput"
            :defaultValue="lastName"
            @input="handleLastNameInput"
          />
        </div>
      </div>
      <div class="DonorDetailBlock__Title">Donation Overview</div>
      <div class="DonorDetailBlock__Donation">
        <div class="DonorDetailBlock__DonationBlock">
          <div class="DonorDetailBlock__DonationBlockUpper">
            <div class="DonorDetailBlock__DonationTitle">
              Lasest Donation
            </div>
            <div class="DonorDetailBlock__Amount">
              <div class="DonorDetailBlock__Currency">
                {{ currency }}
              </div>
              <div class="DonorDetailBlock__Integer">
                {{ latestDonationInteger }}
              </div>
              <div class="DonorDetailBlock__Decimal">
                {{ latestDonationDecimal }}
              </div>
            </div>
          </div>
          <div class="DonorDetailBlock__DonationBlockLower">
            {{ lastDonationDateStr }}
          </div>
        </div>
        <div class="DonorDetailBlock__DonationBlock">
          <div class="DonorDetailBlock__DonationBlockUpper">
            <div class="DonorDetailBlock__DonationTitle">
              Total Giving
            </div>
            <div class="DonorDetailBlock__Amount">
              <div class="DonorDetailBlock__Currency">
                {{ currency }}
              </div>
              <div class="DonorDetailBlock__Integer">
                {{ totalDonationInteger }}
              </div>
              <div class="DonorDetailBlock__Decimal">
                {{ totalDonationDecimal }}
              </div>
            </div>
          </div>
          <div class="DonorDetailBlock__DonationBlockLower">
            {{ firstDonationDateStr }}
          </div>
        </div>
        <div class="DonorDetailBlock__DonationSmallBlock">
          <div class="DonorDetailBlock__DonationBlockUpper">
            <div class="DonorDetailBlock__DonationTitle">
              Recurring Donor?
            </div>
            <div class="DonorDetailBlock__Answer">
              YES
            </div>
          </div>
          <div class="DonorDetailBlock__StatusPart">
            <div class="DonorDetailBlock__StatusDuration">
              {{ statusDurationStr }}
            </div>
            <div class="DonorDetailBlock__Status">
              {{ status }}
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="DonorDetailBlock__Right">
      <div class="DonorDetailBlock__Title">Contact Details</div>
      <div class="DonorDetailBlock__ContactBlock">
        <div class="DonorDetailBlock__SubTitle">Email Address</div>
        <TextInput
          class="DonorDetailBlock__EmailInput"
          :defaultValue="email"
          :readOnly="true"
        />
      </div>
      <div class="DonorDetailBlock__ContactBlock">
        <div class="DonorDetailBlock__SubTitle">Street Address</div>
        <TextInput
          class="DonorDetailBlock__AddressInput"
          :defaultValue="streetAddress"
          @input="handleStreeAddressInput"
        />
      </div>
      <div class="DonorDetailBlock__Address">
        <div class="DonorDetailBlock__CityBlock">
          <div class="DonorDetailBlock__SubTitle">City</div>
          <TextInput
            class="DonorDetailBlock__CityInput"
            :defaultValue="city"
            @input="handleCityInput"
          />
        </div>
        <div class="DonorDetailBlock__StateBlock">
          <div class="DonorDetailBlock__SubTitle">State</div>
          <Select
            class="DonorDetailBlock__State"
            search
            :value="personalDetails.state"
            :items="USStates"
            @select="handleStateChange"
          />
        </div>
        <div class="DonorDetailBlock__ZipBlock">
          <div class="DonorDetailBlock__SubTitle">Zip Code</div>
          <TextInput
            class="DonorDetailBlock__ZipInput"
            :defaultValue="zip"
            @input="handleZipInput"
          />
        </div>
      </div>
    </div>
  </div>
</template>
